target.css:
:root {
  --ink: #24372c;
  --muted: #69776b;
  --paper: #fffdf7;
  --line: #d9dfcf;
  --sage: #e6eedc;
  --leaf: #48704f;
  --fruit: #d66f45;
}

* {
  box-sizing: border-box;
}

.graft-card {
  width: 480px;
  padding: 18px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header,
.kit-head,
footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.eyebrow,
.label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 4px 0 3px;
  font-size: 22px;
  line-height: 1.1;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.status {
  padding: 6px 9px;
  color: var(--leaf);
  background: var(--sage);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 16px 0 12px;
}

.detail {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px;
  background: var(--sage);
  border-radius: 10px;
}

.icon {
  color: var(--fruit);
  font-size: 18px;
  font-weight: 700;
}

.detail strong {
  display: block;
  margin-top: 2px;
  font-size: 13px;
}

.kit {
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
}

.kit-head h2 {
  margin: 0;
  font-size: 13px;
}

.kit-head span {
  color: var(--muted);
  font-size: 11px;
}

ul {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  padding: 0;
  margin: 9px 0 0;
  list-style: none;
}

li {
  display: flex;
  justify-content: space-between;
  padding: 6px 7px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 7px;
  font-size: 11px;
}

li b {
  color: var(--fruit);
}

footer {
  margin-top: 13px;
  color: var(--muted);
  font-size: 11px;
}

button {
  padding: 8px 11px;
  color: var(--paper);
  background: var(--leaf);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}

